import{_ as i,E as a,h as l,c as d,b as e,f as c,H as r,a4 as n,w as h}from"./chunks/framework.B_fYP6Of.js";const v=JSON.parse('{"title":"Embeddings, similarity and the evidence they miss","description":"Learn how embeddings match differently worded questions and passages. Walk through cosine similarity, then check an answer against its source.","frontmatter":{"title":"Embeddings, similarity and the evidence they miss","description":"Learn how embeddings match differently worded questions and passages. Walk through cosine similarity, then check an answer against its source.","teaser":"A club guide calls it application assistance. A visitor calls it help joining. How can a search find the right passage when the words barely overlap?"},"headers":[],"relativePath":"students/embeddings.md","filePath":"students/embeddings.md"}'),p={name:"students/embeddings.md"};function u(m,t,g,b,f,w){const o=a("LabArticleHeader"),s=a("LabScroll");return l(),d("div",null,[t[1]||(t[1]=e("h1",{id:"embeddings-how-can-a-computer-find-related-ideas",tabindex:"-1"},[c("Embeddings: how can a computer find related ideas? "),e("a",{class:"header-anchor",href:"#embeddings-how-can-a-computer-find-related-ideas","aria-label":'Permalink to "Embeddings: how can a computer find related ideas?"'},"​")],-1)),r(o),t[2]||(t[2]=n('<p>A visitor types <strong>“Where can I get help joining?”</strong> The club guide says <strong>“Contact the club secretary for application assistance.”</strong> Which words would an exact search match? Which passage would you want a reader to see?</p><p>An <strong>embedding</strong> is a list of numbers a model produces to represent an input such as a question or passage. Many text-retrieval models learn to place related inputs near one another. A search uses those numbers to choose passages to read. You still need the original sentence to tell the visitor where to go.</p><p><strong>Try it first.</strong> Predict the source, then run the <a href="#short-student-exercise">offline exercise</a>. You can test keyword retrieval without an account. The <a href="#a-geometric-thought-experiment-not-a-model-output">two-number example</a> explains what a similarity score measures.</p><h2 id="the-people-and-the-question" tabindex="-1">The people and the question <a class="header-anchor" href="#the-people-and-the-question" aria-label="Permalink to &quot;The people and the question&quot;">​</a></h2><p>Researchers had the <em>document matching</em> problem long before modern LLMs. Gerard Salton and colleagues&#39; information-retrieval work explored representing documents in mathematical spaces. <a href="https://ecommons.cornell.edu/entities/publication/dc340f22-1c38-4f0a-921e-27706685b1bf" target="_blank" rel="noreferrer">Read the Cornell paper</a>. The vector-space concept evolved over time; don&#39;t confuse early term-weighted document vectors with neural embeddings.</p><p><strong>Tomas Mikolov and colleagues</strong> published <a href="https://arxiv.org/abs/1301.3781" target="_blank" rel="noreferrer">efficient neural word representations</a>. <strong>Nils Reimers and Iryna Gurevych</strong> introduced <a href="https://aclanthology.org/D19-1410/" target="_blank" rel="noreferrer">Sentence-BERT</a> for useful sentence representations in similarity search. For retrieval, one practical advantage is that a system can encode documents ahead of time and compare a new question with the stored vectors.</p><h2 id="word-sentence-paragraph-and-chunk" tabindex="-1">Word, sentence, paragraph and chunk <a class="header-anchor" href="#word-sentence-paragraph-and-chunk" aria-label="Permalink to &quot;Word, sentence, paragraph and chunk&quot;">​</a></h2>',7)),r(s,{kind:"table",label:"table for Word, sentence, paragraph and chunk"},{default:h(()=>[...t[0]||(t[0]=[e("table",{tabindex:"0"},[e("thead",null,[e("tr",null,[e("th",{scope:"col"},"Level"),e("th",{scope:"col"},"Example input"),e("th",{scope:"col"},"What the representation can help compare")])]),e("tbody",null,[e("tr",null,[e("td",null,"Word"),e("td",null,"“membership”"),e("td",null,"Terms (especially with older word-embedding methods)")]),e("tr",null,[e("td",null,"Sentence"),e("td",null,"“Ask the secretary for help.”"),e("td",null,"One statement or intent")]),e("tr",null,[e("td",null,"Paragraph"),e("td",null,"Several sentences describing applications"),e("td",null,"A coherent passage and its context")]),e("tr",null,[e("td",null,"Chunk"),e("td",null,"A section of a long policy with a source ID"),e("td",null,"A retrievable passage with traceable provenance")])])],-1)])]),_:1}),t[3]||(t[3]=n('<p>The same model may accept several input lengths within its documented limit. <strong>A chunk is the text you chose to keep together. Its embedding is the vector the model computed from that text.</strong> Save the passage and its source ID alongside the vector so a reader can inspect the match.</p><h2 id="a-geometric-thought-experiment-not-a-model-output" tabindex="-1">A geometric thought experiment (not a model output) <a class="header-anchor" href="#a-geometric-thought-experiment-not-a-model-output" aria-label="Permalink to &quot;A geometric thought experiment (not a model output)&quot;">​</a></h2><p>Picture two feature directions: one for <em>membership</em> and one for <em>events</em>. We invent tiny vectors:</p><ul><li>Question about joining: <strong>q = (1, 0)</strong></li><li>Membership passage: <strong>a = (0.8, 0.6)</strong></li><li>Events passage: <strong>b = (0, 1)</strong></li></ul><p>Using <strong>cosine similarity</strong>, compare the directions rather than just the sizes:</p><p>[ \\operatorname{cos}(q,a)=\\frac{q\\cdot a}{\\lVert q\\rVert\\lVert a\\rVert}=0.8, \\qquad \\operatorname{cos}(q,b)=0. ]</p><p>So passage <strong>a</strong> ranks higher for this <em>invented</em> comparison. Real embeddings usually have many dimensions learned by a model; their individual coordinates generally do <strong>not</strong> correspond to human-named topics. <strong>These toy numbers were chosen for teaching and were never returned by an embedding API.</strong></p><p>An embedding workflow is:</p><p>```text Original document (S-membership) ↓ split into traceable chunks S-membership-C01 + its real text + source location ↓ configured embedding model Vector + model/version + chunk ID → stored index</p><p>Question → compatible query embedding → compare / rank vectors → retrieve the original text and source ID → give evidence to a model ```</p><p>Never compare vectors from incompatible embedding models as if they shared a coordinate system. Some retrieval models have different query/document input modes; follow the specific model&#39;s instructions.</p><h2 id="when-embeddings-help—and-fail" tabindex="-1">When embeddings help—and fail <a class="header-anchor" href="#when-embeddings-help—and-fail" aria-label="Permalink to &quot;When embeddings help—and fail&quot;">​</a></h2><p>Semantic retrieval may find paraphrases where exact-term search struggles. But it can also retrieve <strong>the wrong person with a similar biography</strong>, a near-opposite policy statement, or an old version of a rule. Cosine similarity is <strong>not a confidence probability</strong>, and a high score is not a source citation.</p><p>A quick diagnostic is to look at the retrieved passage before reading the generated answer. If the correct passage is missing, inspect the query, the chunk boundaries and the embedding model. If the correct passage is present but the answer reverses the rule, check the answer against that passage before changing your search.</p><p>For your IS373 project, compare the same question with a <strong>keyword baseline</strong> and your <strong>chosen vector/graph retrieval</strong>. Inspect returned passage IDs, not only a generated answer. Record whether the cited original supports the specific claim.</p><h3 id="short-student-exercise" tabindex="-1">Short student exercise <a class="header-anchor" href="#short-student-exercise" aria-label="Permalink to &quot;Short student exercise&quot;">​</a></h3><ol><li>Predict which fictional club source answers <strong>“Who helps new applicants?”</strong> and write its expected source ID before searching.</li><li>Run the <a href="./reference#your-first-15-minutes">offline lexical lab</a>. Inspect the returned passage; explain any missed paraphrase.</li><li>If your local environment already supports an embedding model, follow the <a href="./reference#optional-add-a-real-model">optional real vector commands</a>, with the model ID recorded. Otherwise, <strong>label the vector comparison planned</strong>; no subscription is required for the offline step.</li><li>Compare one wrong or irrelevant result and explain how you would improve retrieval: source scope, metadata, chunking, an exact-term baseline, or a different model. Do not invent similarity scores.</li></ol><h3 id="ask-an-ai-coding-partner" tabindex="-1">Ask an AI coding partner <a class="header-anchor" href="#ask-an-ai-coding-partner" aria-label="Permalink to &quot;Ask an AI coding partner&quot;">​</a></h3><p>```text Teach me embeddings using one of my permitted documents and a real question. First distinguish word, sentence, paragraph and chunk representations. Show the original source ID, chunk boundaries and the retrieval result. If you use numeric vectors, say exactly which configured model generated them; label any invented vectors as illustrative. Explain cosine similarity, why the query/document embeddings must be compatible, and one failure case. Do not install packages or generate embeddings until I approve the plan. Ask me to check whether the retrieved passage really answers the question. ```</p><h3 id="a-note-from-the-ai" tabindex="-1">A note from the AI <a class="header-anchor" href="#a-note-from-the-ai" aria-label="Permalink to &quot;A note from the AI&quot;">​</a></h3><blockquote><p>Ask me to point to the original words, version and source location. If I return a score of 0.8, ask what was compared and which model produced the vectors before deciding what the score tells you.</p></blockquote><h2 id="go-deeper-when-ready" tabindex="-1">Go deeper, when ready <a class="header-anchor" href="#go-deeper-when-ready" aria-label="Permalink to &quot;Go deeper, when ready&quot;">​</a></h2><ul><li><a href="https://developers.openai.com/api/docs/guides/embeddings" target="_blank" rel="noreferrer">OpenAI embeddings guide</a> — model vectors, applications, similarity and limitations.</li><li><a href="https://sbert.net/examples/sentence_transformer/applications/semantic-search/" target="_blank" rel="noreferrer">Sentence Transformers semantic search</a> — query and corpus embeddings, similarity and retrieval.</li><li><a href="https://aclanthology.org/D19-1410/" target="_blank" rel="noreferrer">Sentence-BERT paper</a> — a historical research milestone.</li><li><a href="./chunking">Chunking handout</a> — how you choose the text units to embed.</li><li><a href="./check">How to evaluate</a> — accuracy and references, not just a plausible response.</li></ul><p><em>The numerical examples illustrate the geometry. To evaluate a specific model, run the same questions against your own sources.</em></p>',24))])}const k=i(p,[["render",u]]);export{v as __pageData,k as default};
